-- O desenvolvimento utiliza H2 com ddl-auto=create-drop.
-- Este arquivo documenta o modelo relacional para futura migração.
CREATE TABLE clientes (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome VARCHAR(255) NOT NULL, cnpj VARCHAR(64) UNIQUE, email VARCHAR(255), telefone VARCHAR(64));
CREATE TABLE viagens (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, numero VARCHAR(255) NOT NULL, data DATE, status VARCHAR(64), cliente_id BIGINT NOT NULL, CONSTRAINT fk_viagem_cliente FOREIGN KEY (cliente_id) REFERENCES clientes(id));
CREATE TABLE documentos (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome_arquivo VARCHAR(255) NOT NULL, tipo VARCHAR(64) NOT NULL, caminho VARCHAR(1000) NOT NULL, viagem_id BIGINT NOT NULL, CONSTRAINT fk_documento_viagem FOREIGN KEY (viagem_id) REFERENCES viagens(id));
CREATE TABLE envios (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, viagem_id BIGINT NOT NULL, cliente_id BIGINT NOT NULL, data_envio TIMESTAMP, status VARCHAR(32), mensagem VARCHAR(1000), CONSTRAINT fk_envio_viagem FOREIGN KEY (viagem_id) REFERENCES viagens(id), CONSTRAINT fk_envio_cliente FOREIGN KEY (cliente_id) REFERENCES clientes(id));
CREATE INDEX idx_viagens_cliente ON viagens(cliente_id);
CREATE INDEX idx_documentos_viagem ON documentos(viagem_id);
CREATE INDEX idx_envios_viagem ON envios(viagem_id);
